function backupMessage(item, expectedTopic, directory, executionId, at) {
  if (item.topic !== expectedTopic || typeof item.message !== "string")
    throw new Error("The MQTT message is not a backup response for this topic.");
  let result;
  try {
    result = JSON.parse(item.message);
  } catch {
    throw new Error("The MQTT backup response is invalid JSON.");
  }
  if (result?.status !== "ok") throw new Error("Zigbee2MQTT did not report a successful backup.");
  const encoded = result.data?.zip;
  if (typeof encoded !== "string" || !encoded)
    throw new Error("The backup response is missing its ZIP.");
  const bytes = Buffer.from(encoded, "base64");
  if (bytes.toString("base64") !== encoded) throw new Error("The backup ZIP is not valid Base64.");
  if (
    bytes.length < 22 ||
    !["504b0304", "504b0506"].includes(bytes.subarray(0, 4).toString("hex"))
  ) {
    throw new Error("The backup does not contain ZIP bytes.");
  }
  let complete = false;
  for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65557); i--) {
    if (
      bytes.readUInt32LE(i) === 0x06054b50 &&
      i + 22 + bytes.readUInt16LE(i + 20) === bytes.length
    ) {
      complete = true;
      break;
    }
  }
  if (!complete) throw new Error("The backup ZIP archive is incomplete.");
  const folder = directory.trim().replace(/\/+$/, "");
  if (
    !folder ||
    !folder
      .split("/")
      .filter(Boolean)
      .every((segment) => segment !== "." && segment !== ".." && /^[A-Za-z0-9_. -]+$/.test(segment))
  ) {
    throw new Error("Configure a valid SFTP directory.");
  }
  if (typeof executionId !== "string" || !/^\d+$/.test(executionId))
    throw new Error("The workflow did not supply a unique execution ID.");
  const stamp = new Date(at).toISOString().replaceAll(":", "_");
  const fileName = "zigbee_backup_" + stamp + "_" + executionId + ".zip";
  return { zip: encoded, fileName, path: folder + "/" + fileName };
}
const backupDirectory = "zigbee_backups";
const expectedTopic = "zigbee2mqtt/bridge/response/backup";
return { json: backupMessage($json, expectedTopic, backupDirectory, $execution.id, Date.now()) };
